// inventory.query: Read a window of the inventory of a connection
// Generated by `pnpm nx g @app/generators:action inventory.query`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  ExchangeRowSchema,
  INVENTORY_KINDS,
  InventoryFilterSchema,
  InventorySortSchema,
  InventoryWindowSchema,
  QueueRowSchema,
  WINDOW_LIMIT_MAX,
  windowMeta,
} from './explorer-types.ts';

export const InventoryQueryInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  kind: z.enum(INVENTORY_KINDS),
  filter: InventoryFilterSchema.optional(),
  sort: InventorySortSchema.optional(),
  /** Required: there is no "list all" (I-7). */
  window: InventoryWindowSchema,
});

export const InventoryQueryOutputSchema = z.discriminatedUnion('kind', [
  z.strictObject({
    kind: z.literal('queues'),
    rows: z.array(QueueRowSchema).max(WINDOW_LIMIT_MAX),
    ...windowMeta,
  }),
  z.strictObject({
    kind: z.literal('exchanges'),
    rows: z.array(ExchangeRowSchema).max(WINDOW_LIMIT_MAX),
    ...windowMeta,
  }),
]);

export const inventoryQuery = defineAction({
  id: 'inventory.query',
  kind: 'query',
  summary: 'Read a window of the inventory of a connection',
  input: InventoryQueryInputSchema,
  output: InventoryQueryOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({ connectionId: input.cid }),
  http: { method: 'POST', path: '/connections/{cid}/inventory/queries' },
  since: '1.0',
});
